values ('ap_precalculus', 2, '2.8', array['2.8', '2.10', '2.13']::text[], 'vocabulary', 'Invertible function and inverse function', 'A function is invertible on a specified domain if each output is mapped from a unique input; its inverse maps outputs back to inputs so that f(a)=b means f^{-1}(b)=a.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-030; ced=2.8.A.1, 2.8.A.2 "if f(a) = b, then f^-1(b) = a"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.8', array['2.8', '2.10', '2.13']::text[], 'list_sequence', 'Ways to find an inverse', 'Representations of the inverse of y=f(x) on an invertible domain.', '[{"label": "Table", "meaning": "Reverse input-output pairs: (a, b) becomes (b, a); domain and range swap"}, {"label": "Graph", "meaning": "Reflect the graph over the identity function h(x)=x"}, {"label": "Equation", "meaning": "Reverse the roles of x and y in y=f(x), then solve for y=f^{-1}(x)"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-032; ced=2.8.B.2, 2.8.B.3, 2.8.B.4')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.9', array['2.9', '2.10', '2.12', '2.13', '2.14']::text[], 'formula', 'Definition of a logarithm', '\log_b c = a \iff b^{a} = c,\quad b>0,\ b\neq 1', '[]'::jsonb, NULL, 'With no base written, log means the common logarithm with base 10.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-034; ced=2.9.A.1 "log b c = a if and only if b^a = c"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.9', array['2.9', '2.15']::text[], 'vocabulary', 'Logarithmic scale', 'On a logarithmic scale, each unit represents a multiplicative change of the base of the logarithm (for base 10, the units might be 10^0, 10^1, 10^2, ...).', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r2-011; ced=2.9.A.3 "On a logarithmic scale, each unit represents a multiplicative change of the base of the logarithm"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.10', array['2.10', '2.11', '2.14']::text[], 'convention', 'Exponential growth vs. logarithmic growth', 'Exponential growth has outputs changing multiplicatively as inputs change additively; logarithmic growth has outputs changing additively as inputs change multiplicatively.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-039; ced=2.10.A.2 "exponential growth is characterized by output values changing multiplicatively as input values change additively"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.10', array['2.10', '2.11', '2.14']::text[], 'formula', 'General form of a logarithmic function', 'f(x) = a\log_b x,\quad b>0,\ b\neq 1,\ a\neq 0', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-036; ced=2.10.A.1 "f(x) = a log b x, with base b, where b > 0, b ≠ 1, and a ≠ 0"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.10', array['2.10']::text[], 'convention', 'Graph and ordered pairs of log vs. exponential', 'For b>0 and b≠1, the graph of f(x)=log_b x is the reflection of the graph of g(x)=b^x over h(x)=x, so if (s,t) is on g then (t,s) is on f.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r2-012; ced=2.10.A.4 "a reflection of the graph of the exponential function"; 2.10.A.5 "then (t, s) is an ordered pair of the logarithmic function"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.10', array['2.10', '2.13']::text[], 'formula', 'Logarithmic and exponential functions are inverses', 'f(x)=\log_b x,\ g(x)=b^{x}:\quad g(f(x)) = f(g(x)) = x', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-037; ced=2.10.A.3 "f(x) = log b x and g(x) = b^x ... are inverse functions"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.11', array['2.11', '2.14']::text[], 'convention', 'Domain, range, and shape of logarithmic functions', 'A general-form logarithmic function has domain x>0 and range all real numbers; it is always increasing or always decreasing, always concave up or always concave down, with no extrema except on a closed interval and no points of inflection.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-040; ced=2.11.A.1, 2.11.A.2')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.11', array['2.11']::text[], 'formula', 'End behavior and asymptote of logarithmic functions', '\lim_{x\to 0^{+}} a\log_b x = \pm\infty,\quad \lim_{x\to\infty} a\log_b x = \pm\infty;\ \text{vertical asymptote } x=0', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-041; ced=2.11.A.4 "vertically asymptotic to x = 0, with an end behavior that is unbounded"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.11', array['2.11']::text[], 'convention', 'Recognizing logarithmic behavior via additive transformation', 'If g(x)=f(x+k) with k≠0 for a general-form logarithmic f, its input values are not proportional over equal-length output intervals; but if the input values of g(x)=f(x+k) for any function f are proportional over equal-length output intervals, then f is logarithmic.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r2-014; ced=2.11.A.3 "if the input values of the additive transformation function, g(x) = f(x + k), of any function f are proportional over equal-length output value intervals, then f is logarithmic"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.12', array['2.12', '2.13']::text[], 'formula', 'Change of base property', '\log_b x = \frac{\log_a x}{\log_a b},\quad a>0,\ a\neq 1', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-045; ced=2.12.A.3 "This implies that all logarithmic functions are vertical dilations of each other."')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.12', array['2.12', '2.14']::text[], 'formula', 'Natural logarithm', '\ln x=\log_{e} x', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r2-013; ced=2.12.A.4 "ln x = log_e x"')
