values ('ap_precalculus', 2, '2.12', array['2.12', '2.13']::text[], 'formula', 'Power property for logarithms', '\log_b x^{n} = n\log_b x', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-044; ced=2.12.A.2 "log b x^n = n log b x"')
