values ('ap_precalculus', 2, '2.12', array['2.12', '2.13']::text[], 'formula', 'Product property for logarithms and horizontal dilation', '\log_b(xy) = \log_b x + \log_b y;\quad \log_b(kx) = \log_b k + \log_b x', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-043; ced=2.12.A.1 "every horizontal dilation of a logarithmic function ... is equivalent to a vertical translation"')
