insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.13', array['2.13']::text[], 'convention', 'Check for extraneous solutions', 'After solving exponential or logarithmic equations, examine results for extraneous solutions ruled out by mathematical or contextual limitations (e.g. b^x is always positive and log arguments must be positive).', '[]'::jsonb, NULL, 'State explicitly which candidate solutions are rejected and why.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-048; ced=2.13.A.2 "results should be examined for extraneous solutions precluded by the mathematical or contextual limitations"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.13', array['2.13']::text[], 'formula', 'Rewriting an exponential in a different base', 'b^{x} = c^{(\log_c b)(x)}', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-047; ced=2.13.A.3 "Specifically, b^x = c^((log_c b)(x))"')
