insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.13', array['2.13']::text[], 'formula', 'Transformed exponential and logarithmic forms to invert', 'f(x) = ab^{x+h} + k;\quad f(x) = a\log_b(x+h) + k', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-049; ced=2.13.B.1, 2.13.B.2 "combination of additive transformations"; "determining the inverse operations to reverse the mapping"')
