insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.14', array['2.14']::text[], 'convention', 'Constructing logarithmic models', 'A logarithmic model is built from a proportion and a real zero or from two input-output pairs, by transformations of f(x)=a log_b x, or with a logarithmic regression, and can predict dependent values or determine independent values.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-050; ced=2.14.A.2 "an appropriate proportion and a real zero or from two input-output pairs"; 2.14.A.3; 2.14.A.4; 2.14.A.6')
