values ('ap_precalculus', 2, '2.15', array['2.15']::text[], 'formula', 'Semi-log linearization of an exponential model', 'y = ab^{x}\ \longrightarrow\ \log_n y = (\log_n b)\,x + \log_n a', '[]'::jsonb, NULL, 'Slope of the semi-log line is log_n b and the initial linear value is log_n a, not b and a.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-052; ced=2.15.B.2 "y = (log n b) x + log n a ... the linear rate of change is log n b, and the initial linear value is log n a"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.15', array['2.15']::text[], 'vocabulary', 'Semi-log plot', 'A plot in which one axis is logarithmically scaled with base n > 1; when the y-axis is log-scaled, exponential data or functions appear linear.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-051; ced=2.15.A.1 "logarithmically scaled with logarithm base n, where n > 1 ... will appear linear"')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_precalculus', 2, '2.15', array['2.15']::text[], 'convention', 'Using a semi-log plot to justify an exponential model', 'If the logarithms of output values trend linear for large inputs, transformations of an exponential function can model the data, and the dependent values need not be shifted by a constant to see this.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-precalculus-reference-u1-u3-2026-10-10; candidate=ap_precalculus-u2-r1-053; ced=2.15.A.2 "the dependent variable values do not need to be transformed by a constant"')
